param([switch]$Server)
$ErrorActionPreference='Stop'
[Console]::OutputEncoding=[System.Text.UTF8Encoding]::new($false)
$Base=Split-Path -Parent $PSCommandPath
$Root=Join-Path $Base 'world-hub'
$Edu='C:\Users\Lenovo\Desktop\Edu'
$PidFile=Join-Path $Edu 'K6A.pid'
$PortFile=Join-Path $Edu 'K6A.port'
function ContentType([string]$p){switch([IO.Path]::GetExtension($p).ToLowerInvariant()){'.html'{'text/html; charset=utf-8'}'.js'{'application/javascript; charset=utf-8'}'.css'{'text/css; charset=utf-8'}'.json'{'application/json; charset=utf-8'}'.svg'{'image/svg+xml'}'.png'{'image/png'}'.jpg'{'image/jpeg'}'.jpeg'{'image/jpeg'}'.webp'{'image/webp'}'.mp3'{'audio/mpeg'}default{'application/octet-stream'}}}
if($Server){$listener=$null;$port=$null;foreach($candidate in 8789..8799){$try=[Net.HttpListener]::new();$try.Prefixes.Add("http://127.0.0.1:$candidate/");try{$try.Start();$listener=$try;$port=$candidate;break}catch{try{$try.Close()}catch{}}};if(!$listener){exit 20};Set-Content $PortFile $port -Encoding ascii;try{while($listener.IsListening){$ctx=$listener.GetContext();$rel=[Uri]::UnescapeDataString($ctx.Request.Url.AbsolutePath.TrimStart('/'));if([string]::IsNullOrWhiteSpace($rel)){$rel='index.html'};$rel=$rel-replace'/',[IO.Path]::DirectorySeparatorChar;$full=[IO.Path]::GetFullPath((Join-Path $Root $rel));$rootFull=[IO.Path]::GetFullPath($Root);$ctx.Response.Headers['Cache-Control']='no-store, no-cache, must-revalidate, max-age=0';if(!$full.StartsWith($rootFull,[StringComparison]::OrdinalIgnoreCase)){$ctx.Response.StatusCode=403;$bytes=[Text.Encoding]::UTF8.GetBytes('Forbidden')}elseif(Test-Path $full -PathType Leaf){$ctx.Response.StatusCode=200;$ctx.Response.ContentType=ContentType $full;$bytes=[IO.File]::ReadAllBytes($full)}else{$ctx.Response.StatusCode=404;$bytes=[Text.Encoding]::UTF8.GetBytes('Not found')};$ctx.Response.ContentLength64=$bytes.Length;$ctx.Response.OutputStream.Write($bytes,0,$bytes.Length);$ctx.Response.OutputStream.Close()}}finally{try{$listener.Stop()}catch{};try{$listener.Close()}catch{}};exit 0}
